public class AuditClockProbe {
 public static Map<String,Object> run() {
  Savepoint marker=Database.setSavepoint();
  Account first=new Account(Name='Synthetic first'); insert first;
  Account second=new Account(Name='Synthetic second'); insert second;
  Datetime checkpoint=Datetime.now();
  Integer futureBefore=[SELECT count() FROM Account WHERE LastModifiedDate > :checkpoint];
  Account original=[SELECT CreatedDate,LastModifiedDate FROM Account WHERE Id=:first.Id];
  first.Name='Synthetic changed'; update first;
  Datetime afterUpdate=Datetime.now();
  Account changed=[SELECT CreatedDate,LastModifiedDate FROM Account WHERE Id=:first.Id];
  Integer futureAfter=[SELECT count() FROM Account WHERE LastModifiedDate > :afterUpdate];
  Map<String,Object> result=new Map<String,Object>{'futureAfterInserts'=>futureBefore,'futureAfterUpdate'=>futureAfter,'createdPreserved'=>original.CreatedDate==changed.CreatedDate,'createdNotFuture'=>changed.CreatedDate<=afterUpdate,'modifiedNotFuture'=>changed.LastModifiedDate<=afterUpdate,'createdMillis'=>original.CreatedDate.getTime(),'modifiedMillis'=>changed.LastModifiedDate.getTime(),'checkpointMillis'=>checkpoint.getTime(),'afterUpdateMillis'=>afterUpdate.getTime()};
  Database.rollback(marker);return result;
 }
}

